INSERT INTO `bot_faqs` VALUES
(2,'deposit, transfer, bayar, berapa, minimal, saldo, isi dana, top up, deponya, depo, cara deponya','Buat deposit minimal $10/100k aja kak gampang kok bisa pake QRIS atau Bank Lokal. Tonton video panduannya di sini ya:\n[VIDEO: deposit]','reply_only'),
(3,'withdraw, tarik, penarikan, cair','Buat penarikan dana (Withdraw) cepat dan gampang kak, bisa langsung masuk ke rekening lokal. Tonton panduan videonya di sini ya\n[VIDEO: wd]','reply_only'),
(4,'kolom ib tidak tampil, tidak ada kolom ib, gak ada kolom ib, kolom ib tidak muncul, kolom ib tidak ada, ib tidak muncul, ib gak ada, ib tidak terlihat, tidak tampil kolom ib, kolom ib hilang, clear cache, hapus cache','Waduh kak {NAMA_USER}, kolom IB tidak muncul ya? Tenang, biasanya karena cache browser yang perlu dibersihkan.\r\n\r\nCara Clear Cache di Google Chrome:\r\n1. Klik Titik 3 sebelah Kanan atas\r\n2. Klik Hapus Data Penjelajahan\r\n3. Klik Opsi Lainnya\r\n4. Centang semua pilihan\r\n5. Klik Hapus data\r\n\r\nSetelah clear cache, refresh halaman login dan coba lagi ya!\r\nJangan lupa kirim ScreenShoot nya ya.\r\n\r\nGambar panduan:\r\n[GAMBAR: kolom_ib_tidak_muncul]','reply_only'),
(5,'tidak jadi, skip, nanti aja, batal, cancel, gak jadi, ga jadi, stop, males','Oke kak {NAMA_USER}, santai aja ya. Kalau nanti berubah pikiran atau butuh bantuan lagi, tinggal chat aku lagi ya. Sukses selalu kak!','reply_only'),
(6,'cek id, mau cek, ngecek, status, acc, kok lama, cek under ib','Boleh kak! Langsung kirim aja ANGKA ID trading MT5-nya ke sini biar aku cek ya','reply_only'),
(7,'arsip, cara arsip, arsipkan, gimana arsip, cara arsipkan','Sekarang lanjut untuk ARSIPKAN SEMUA AKUN TRADING Lamanya.\r\n\r\nCara Arsip Akun:\r\n1. G boleh ada Posisi yg berjalan atau pending order\r\n2. Saldo Wajib 0 ( Kalau masih ada saldo harap pindahkan ke wallet terlebih dahulu)\r\n3. Tonton video tutorial dibawah ini.\r\n[VIDEO: arsipkan_akun]\r\n\r\nKalo udah diarsipkan, kirim Screenshot buktinya ke sini ketik \'lanjut\' atau \'selesai\' ya kak!','reply_only');
INSERT INTO `bot_flows` VALUES
(1,1,'Tanya Status Akun','halo, hai, pagi, siang, sore, malam, assalam, start, mulai, iya, mau, ya, oke, ok, y, betul, mau join, yes, assalamualaikum, ','Halo kak {NAMA_USER}! Udah punya akun HFM belom nih?','Maaf kak, jawab *sudah* atau *belum* punya akun HFM ya biar aku bisa bantu arahkan.','',NULL),
(2,2,'Daftar Akun Baru (Belum Punya)','belum, tidak, blum, nggak, gk, enggak, belom, ga punya, gak punya, blm, belom, gak ada, gak, gk ada','✔️Klik  LINK REGIS HFM\r\n{LINK_DAFTAR}\r\n\r\n✔️Isi data sesuai nama lengkap \r\n✔️Upload KTP or SIM\r\n✔️Buka Akun trading (Bebas pilih apa aja)\r\n✔️Deposit > Min $10  \r\n\r\n- ScreenShoot Bagian Akun Trading\r\n\r\n BACA SEMUA BARU TANYA 🤬\r\n\r\n[VIDEO: ktp]','','',NULL),
(3,4,'Pindah IB (Sudah Punya)','sudah, udah, ada, sdh, udh, dah, punya, pindah ib, ganti ib, cara pindah','Kak {NAMA_USER}, untuk pindah IB ke under BOSSCUAN caranya seperti ini:\r\n\r\nLogin via Web menggunakan Link Berikut :\r\nhttp://hftidtrade.com\r\n\r\nCara Pindah IB:\r\n1. Klik Dompet Saya\r\n2. Klik Aksi Wallet\r\n3. Klik set ID Mitra & Kampanye\r\n4. Ketik {KODE_IB} dibagian ID Mitra & Kampanye\r\n5. Klik Tambah\r\n6. Lalu klik tetapkan Ulang.\r\n\r\nIkutin Sesuai Video Tutorial ya. Jangan Lupa SS ketika sudah berhasil.\r\n[VIDEO: pindah_ib]','Kak, aku belum bisa mendeteksi teks dari screenshotnya. Mohon kirim ulang screenshot bukti pindah IB-nya ya!','',NULL),
(4,5,'Arsip Akun','arsip_sukses, berhasil pindah, cara arsip','Kak {NAMA_USER} ini caranya:\r\n\r\nCara Arsip Akun:\r\n1. Login ke Web HFM\r\n2. Klik menu Akun Saya\r\n3. Pilih akun yang mau diarsipkan\r\n4. Klik tombol Arsipkan\r\n5. Ulangi untuk semua akun kecuali 1 akun aktif\r\n\r\nTonton video tutorial singkat ini ya\r\n[VIDEO: arsipkan_akun]\r\n\r\nKalo udah diarsipkan semua, kirim *Screenshot* buktinya ke sini ya kak!','','',NULL),
(5,6,'Buka MT5 & Deposit','selesai, done, lanjut, beres, mantap, next, sukses','Mantap kak {NAMA_USER}!\r\n\r\n1. Buka akun trading Live MT5 (bebas pilih tipe)\r\n2. Pastikan memasukkan Kode IB {KODE_IB} di kolom Introducing Broker\r\n3. Deposit minimal Rp100.000\r\n\r\nTonton videonya: [VIDEO: buka_akun]\r\n\r\n⚠️ Kalo udah deposit, Ketik *Angka Akun ID trading* barunya ke sini ya kak!','','',NULL),
(6,3,'SS Akun Trading','saya sudahregis, sudah daftar, selanjutnya, ','Klik lalu ss bagian ini\r\n[GAMBAR: ss_akunsaya]\r\n[GAMBAR: ss_akunsayaapk]','','',NULL);
